type SqlValue = string | number | null;
type Row = Readonly<Record<string, SqlValue>>;

type Vehicle = {
  readonly id: number;
  readonly fingerprint: string;
  readonly make: string | null;
  readonly model: string | null;
  readonly family: string;
  readonly year: number | null;
  readonly km: number | null;
  readonly price: number | null;
  readonly city: string | null;
  readonly postal_code: string | null;
  readonly lat: number | null;
  readonly lon: number | null;
  readonly distance_km: number | null;
  readonly status: string;
  readonly do_not_contact: number;
  readonly matched: number;
  readonly reasons: string;
  readonly message_override: string | null;
  readonly first_seen_at: string;
  readonly last_seen_at: string;
  readonly notified_at: string | null;
  readonly price_dropped: number;
  readonly reposted: number;
  readonly note: string | null;
  readonly published_at: string | null;
};

type VehicleSeed = Omit<
  Vehicle,
  'reasons' | 'status' | 'do_not_contact' | 'message_override' | 'last_seen_at' | 'notified_at' | 'price_dropped' | 'reposted' | 'note'
> &
  Partial<
    Pick<Vehicle, 'status' | 'do_not_contact' | 'message_override' | 'last_seen_at' | 'notified_at' | 'price_dropped' | 'reposted' | 'note'>
  > & {
    readonly reasons: readonly string[];
  };

type Listing = {
  readonly id: number;
  readonly vehicle_id: number;
  readonly site: string;
  readonly site_label: string;
  readonly external_id: string;
  readonly url: string;
  readonly title: string;
  readonly price: number | null;
  readonly km: number | null;
  readonly year: number | null;
  readonly city: string | null;
  readonly postal_code: string | null;
  readonly seller_type: string;
  readonly image_url: string | null;
  readonly description: string | null;
  readonly published_at: string | null;
  readonly source_ref: string | null;
  readonly first_seen_at: string;
  readonly last_seen_at: string;
};

type ListingSeed = Omit<Listing, 'image_url' | 'description' | 'published_at' | 'source_ref' | 'last_seen_at'> &
  Partial<Pick<Listing, 'image_url' | 'description' | 'published_at' | 'source_ref' | 'last_seen_at'>>;

type PricePoint = { readonly listing_id: number; readonly price: number; readonly seen_at: string };
type VehicleEvent = { readonly vehicle_id: number; readonly type: string; readonly detail: string | null; readonly at: string };

type ParsedListing = {
  readonly title: string;
  readonly price?: number;
  readonly km?: number;
  readonly year?: number;
  readonly city?: string;
  readonly postalCode?: string;
  readonly sellerType?: string;
  readonly url: string;
};

type ParsedEmail = {
  readonly listings: readonly ParsedListing[];
  readonly pending: number;
  readonly ignored: number;
  readonly announced?: number;
  readonly kind: string;
  readonly moreUrl?: string;
};

const vehicle = (seed: VehicleSeed): Vehicle => ({
  status: 'nouveau',
  do_not_contact: 0,
  message_override: null,
  last_seen_at: seed.first_seen_at,
  notified_at: null,
  price_dropped: 0,
  reposted: 0,
  note: null,
  ...seed,
  reasons: JSON.stringify(seed.reasons),
});

const listing = (seed: ListingSeed): Listing => ({
  image_url: null,
  description: null,
  published_at: null,
  source_ref: null,
  last_seen_at: seed.first_seen_at,
  ...seed,
});

const event = (vehicleId: number, type: string, at: string, detail: string | null = null): VehicleEvent => ({
  vehicle_id: vehicleId,
  type,
  detail,
  at,
});

const parsed = (email: ParsedEmail): string =>
  JSON.stringify({
    listings: email.listings,
    pending: email.pending,
    ignored: email.ignored,
    announced: email.announced,
    kind: email.kind,
    moreUrl: email.moreUrl,
  });

