const fixture = (name: string): string => readFileSync(new URL(name, import.meta.url), 'utf8');

const insertAll = (db: Database.Database, table: string, rows: readonly Row[]): void => {
  const columns = Object.keys(rows[0] ?? {});
  const statement = db.prepare(`INSERT INTO ${table} (${columns.join(', ')}) VALUES (${columns.map((c) => `@${c}`).join(', ')})`);
  for (const row of rows) statement.run(row);
};

export function buildLegacyDatabase(file: string): void {
  const db = new Database(file);
  try {
    db.pragma('journal_mode = WAL');
    db.pragma('foreign_keys = ON');
    db.exec(fixture('./schema-legacy.sql'));
    db.transaction(() => {
      insertAll(db, 'settings', [{ key: 'main', json: JSON.stringify(JSON.parse(fixture('./settings-legacy.json'))) }]);
      insertAll(db, 'secrets', SECRETS);
      insertAll(db, 'sessions', SESSIONS);
      insertAll(db, 'push_subscriptions', PUSH_SUBSCRIPTIONS);
      insertAll(db, 'geo_cache', GEO_CACHE);
      insertAll(db, 'vehicles', VEHICLES);
      insertAll(db, 'listings', LISTINGS);
      insertAll(db, 'price_history', PRICE_HISTORY);
      insertAll(db, 'events', EVENTS);
      insertAll(db, 'emails_processed', EMAILS);
      insertAll(db, 'mail_state', MAIL_STATE);
      insertAll(db, 'source_runs', SOURCE_RUNS);
    })();
  } finally {
    db.close();
  }
}
